INSERT IGNORE INTO glossary_term (term, aliases, definition, usage_note, related, source, status, created_by, submitted_by, reviewed_by, reviewed_at, review_comment) VALUES
('정기공시', '정기보고서', '회사가 정해진 때마다 내는 보고서입니다. 사업보고서(1년), 반기보고서(6개월), 분기보고서(3개월)가 있습니다.', '분석은 같은 종류의 정기보고서끼리 비교합니다(올해 사업보고서 ↔ 작년 사업보고서).', '사업보고서,반기보고서,분기보고서', '자본시장법 제159조·제160조', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('사업보고서', NULL, '1년 동안의 사업 내용과 재무 상태를 정리한 보고서입니다. 사업연도가 끝난 뒤 90일 안에 냅니다.', '보고서 코드 11011. 비교 분석의 기본 대상입니다.', '정기공시,보고서 코드', '자본시장법 제159조', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('반기보고서', NULL, '사업연도 앞 6개월의 실적과 사업 내용을 담은 보고서입니다. 반기가 끝난 뒤 45일 안에 냅니다.', '보고서 코드 11012.', '정기공시,분기보고서', '자본시장법 제160조', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('분기보고서', '1분기보고서,3분기보고서', '1분기·3분기의 실적과 사업 내용을 담은 보고서입니다. 분기가 끝난 뒤 45일 안에 냅니다.', '보고서 코드 11013(1분기), 11014(3분기).', '정기공시,반기보고서', '자본시장법 제160조', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('주요사항보고서', NULL, '소송 제기, 유상증자, 전환사채 발행처럼 중요한 일이 생기면 바로 내는 수시공시입니다.', '리포트 검증에서 소송 금액 등을 교차 확인하는 데 씁니다.', '정기공시', '자본시장법 제161조', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('정정공시', '기재정정,[기재정정]', '이미 낸 보고서의 내용을 고쳐 다시 낸 것입니다. 새 접수번호가 붙고 보고서명 앞에 [기재정정]이 붙습니다.', '같은 기간 보고서가 여러 개면 가장 최근 정정본을 씁니다.', '접수번호', 'OpenDART 개발가이드', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('접수번호', 'rcept_no', 'DART가 보고서 한 건마다 붙이는 14자리 번호입니다. 앞 8자리가 접수일입니다.', '리포트의 모든 출처가 이 번호를 가리키고, 누르면 DART 원문으로 이동합니다.', '고유번호,정정공시', 'OpenDART 개발가이드', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('고유번호', 'corp_code', 'DART가 회사마다 붙이는 8자리 번호입니다. 상장하지 않은 회사에도 있습니다.', '공시레이더에서 회사를 구분하는 기본 키입니다.', '종목코드,접수번호', 'OpenDART 개발가이드', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('종목코드', 'stock_code', '증권시장에 상장된 종목에 붙는 6자리 번호입니다. 상장사에만 있습니다.', '시세 조회와 회사 검색에 씁니다.', '고유번호', '한국거래소', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('보고서 코드', 'reprt_code', 'OpenDART에서 보고서 종류를 나타내는 5자리 코드입니다. 11011 사업, 11012 반기, 11013 1분기, 11014 3분기보고서입니다.', '분석 요청과 재무 조회에서 보고서 종류를 고를 때 씁니다.', '사업보고서,반기보고서,분기보고서', 'OpenDART 개발가이드', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('연결재무제표', '연결,CFS', '모회사와 지배하는 종속회사를 하나의 회사처럼 합쳐 만든 재무제표입니다.', '있으면 연결을 쓰고, 출처마다 연결/별도를 표시합니다. 비교하는 두 기간은 같은 범위여야 합니다.', '별도재무제표,지배주주', 'K-IFRS', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('별도재무제표', '별도,OFS', '종속회사를 합치지 않고 회사 하나만의 숫자로 만든 재무제표입니다.', '연결재무제표가 없을 때 씁니다.', '연결재무제표', 'K-IFRS', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('재무상태표', 'BS', '정해진 날짜(기말) 기준으로 회사가 가진 자산과 진 부채, 자본을 보여 주는 표입니다.', '자본총계·지배주주 자본은 PBR 계산에 씁니다.', '손익계산서,자본총계', 'K-IFRS', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('손익계산서', 'IS,포괄손익계산서,CIS', '일정 기간 동안 얼마를 팔고(매출), 얼마를 남겼는지(이익)를 보여 주는 표입니다.', '매출액·영업이익·당기순이익의 증감을 계산합니다.', '재무상태표,매출액,영업이익', 'K-IFRS', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('매출액', '매출,수익(매출액),영업수익', '회사가 제품이나 서비스를 팔아 번 돈의 합계입니다. 비용을 빼기 전 금액입니다.', '중요 변동 판단의 기준(변동액이 매출의 1% 이상)으로도 씁니다.', '영업이익,영업이익률', 'K-IFRS', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('영업이익', '영업이익(손실)', '매출액에서 원가와 판매·관리에 든 비용을 뺀 금액입니다. 본업으로 번 이익을 보여 줍니다.', '주요 계정 증감과 영업이익률 계산에 씁니다.', '매출액,영업이익률,당기순이익', 'K-IFRS', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('영업이익률', NULL, '영업이익을 매출액으로 나눈 비율입니다. 1만 원어치 팔았을 때 본업으로 얼마가 남았는지를 뜻합니다.', '기업 목록과 기업 상세에 표시합니다. 계산식을 펼쳐 볼 수 있습니다.', '영업이익,매출액', 'K-IFRS', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('당기순이익', '순이익,당기순이익(손실)', '영업이익에 영업 외 손익과 법인세까지 반영한 뒤 최종으로 남은 이익입니다.', '연결재무제표에서는 지배주주 몫과 비지배지분 몫으로 나뉩니다.', '지배주주 순이익,영업이익', 'K-IFRS', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('지배주주 순이익', '지배주주,지배기업 소유주지분,지배기업의 소유주에게 귀속되는 당기순이익', '연결 당기순이익 가운데 모회사 주주에게 돌아가는 몫입니다. 종속회사의 다른 주주 몫(비지배지분)은 뺀 금액입니다.', 'PER 계산에 씁니다. 이 계정이 없으면 전체 당기순이익으로 대신하고 "대체 계정"이라고 표시합니다.', '당기순이익,PER,연결재무제표', 'K-IFRS', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('자본총계', '자본,지배주주 자본', '자산에서 부채를 뺀 금액입니다. 연결에서는 모회사 주주 몫(지배주주 자본)을 따로 봅니다.', 'PBR 계산에 지배주주 자본을 씁니다. 0 이하(자본잠식)면 PBR을 계산하지 않습니다.', '재무상태표,PBR', 'K-IFRS', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('누적 금액', '누적,add_amount', '반기·분기보고서의 손익에서 사업연도 시작부터 그 기간 끝까지 더한 금액입니다. 해당 3개월만의 금액과 다릅니다.', 'TTM 계산은 누적 금액을 씁니다.', 'TTM,분기보고서', 'OpenDART 개발가이드', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('TTM', '최근 12개월,Trailing Twelve Months', '가장 최근 12개월 동안의 합계입니다. 최근 연간 + 올해 누적 − 작년 같은 기간 누적으로 구합니다.', 'PER(TTM)과 기업 상세의 TTM 매출·영업이익·순이익에 씁니다.', 'PER,누적 금액', '공시레이더 계산 규칙', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('시가총액', '시총', '주가에 상장주식수를 곱한 값입니다. 시장에서 매겨진 회사 전체의 가격입니다.', 'PER·PBR의 분자이고, 업종 지도에서 칸의 크기입니다. 기준일을 함께 표시합니다.', 'PER,PBR,종가', '공공데이터포털 금융위원회 주식시세정보', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('PER', '주가수익비율', '시가총액을 지배주주 순이익으로 나눈 값입니다. 지금 가격이 1년 이익의 몇 배인지를 뜻합니다.', '이익이 0 이하면 계산하지 않습니다. 계산 결과만 보여 주고 해석은 하지 않습니다.', '시가총액,지배주주 순이익,TTM', '공시레이더 계산 규칙', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('PBR', '주가순자산비율', '시가총액을 지배주주 자본으로 나눈 값입니다. 지금 가격이 장부상 순자산의 몇 배인지를 뜻합니다.', '자본이 0 이하면 계산하지 않습니다. 계산 결과만 보여 주고 해석은 하지 않습니다.', '시가총액,자본총계', '공시레이더 계산 규칙', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('종가', 'clpr', '그날 거래가 끝났을 때의 마지막 가격입니다.', '시가총액과 지수 추이에 씁니다. 공공데이터포털 시세는 다음 영업일 오후에 올라옵니다.', '시가총액', '공공데이터포털 금융위원회 주식시세정보', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('KSIC', '한국표준산업분류,업종 코드', '통계청이 정한 한국표준산업분류입니다. 회사의 주된 사업을 업종 코드로 나타냅니다.', '시장 화면의 업종 지도에서 회사를 업종별로 묶습니다.', '시가총액', '통계청 한국표준산업분류', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('최대주주', '특수관계인', '회사 지분을 가장 많이 가진 주주입니다. 친족·계열회사 등 특수관계인의 지분을 합쳐 봅니다.', '지배구조 탭에서 기초·기말 지분 변화를 보여 줍니다.', '타법인출자', '사업보고서 VII. 주주에 관한 사항', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('타법인출자', NULL, '회사가 다른 회사의 지분을 사서 가지고 있는 것입니다.', '지배구조 탭에서 신규 출자와 지분 변화를 보여 줍니다.', '최대주주', '사업보고서 타법인출자 현황', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('변경 문단', '변동 항목', '올해 보고서와 작년 보고서를 문단끼리 짝지어 비교했을 때 새로 생기거나(신설), 없어지거나(삭제), 표현·숫자가 바뀐(수정) 문단입니다.', '리포트의 "변경 문단" 구역에 중요도 순으로 나옵니다.', '관련 서술,검증 결과', '공시레이더', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('관련 서술', NULL, '숫자가 크게 바뀐 계정마다, 그 이유를 설명하는 원문 문장을 찾아 붙인 것입니다.', '리포트의 "수치·관련 서술" 구역. 문장마다 원문 문단을 인용합니다.', '변경 문단,인용', '공시레이더', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('검증 결과', '통과,재작성 후 통과,반려,검토 필요', '리포트 문장을 코드로 검사한 결과입니다. 인용이 있는지, 숫자와 증감 방향이 원문·재무와 맞는지, 금지 표현이 없는지 봅니다.', '통과하지 못한 항목에는 "검토 필요"와 실패한 검사 이름이 붙습니다.', '관련 서술,출력 필터', '공시레이더', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('인용', '근거,인용 ID', '리포트 문장이 근거로 삼은 원문 문단입니다. 문단마다 번호(인용 ID)가 있어 원문 위치로 바로 갈 수 있습니다.', '모든 변경·관련 서술 문장에 붙습니다.', '접수번호,관련 서술', '공시레이더', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('발행 원장', 'Core', '결재자가 승인해 발행된 리포트의 정본 기록입니다. 지우거나 고치지 않고, 고칠 때는 새 버전을 정정 발행합니다.', '발행 원장 메뉴에서 버전·상태·결정자를 볼 수 있습니다.', '정정 발행,결재', '공시레이더', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('정정 발행', 'SUPERSEDED,대체됨', '이미 발행한 리포트를 고쳐 새 버전으로 다시 발행하는 것입니다. 승인되면 이전 버전은 "대체됨"이 되고 두 버전 모두 남습니다.', '같은 회사·기간에 발행된 건이 있으면 발행 요청이 자동으로 정정 발행이 됩니다.', '발행 원장', '공시레이더', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
('출력 필터', '금지 표현', 'AI가 쓴 문장과 사람이 고친 문장에서 투자 권유나 가치판단으로 읽힐 표현을 찾아 고쳐 쓰거나 막는 장치입니다.', '리포트 수정, 용어 정의 게시 때도 같은 필터를 거칩니다.', '검증 결과', '자본시장법(투자자문업) 관련 표현 기준', 'PUBLISHED', 'seed', 'seed', 'seed', NOW(6), '초기 데이터'),
